function bool(text,values){const tokens=text.match(/[ABC01]|[¬∧∨⊕()]/g)||[];assert.equal(tokens.join(''),text.replace(/\s/g,''));let i=0;function atom(){const t=tokens[i++];if(t==='¬')return 1-atom();if(t==='('){const v=expr(0);assert.equal(tokens[i++],')');return v}if(t==='0'||t==='1')return Number(t);assert.ok(Object.hasOwn(values,t));return values[t]}const priority={'∨':1,'⊕':2,'∧':3};function expr(min){let a=atom();while((priority[tokens[i]]||0)>min){const op=tokens[i++],b=expr(priority[op]);a=op==='∨'?a|b:op==='∧'?a&b:a^b}return a}const r=expr(0);assert.equal(i,tokens.length);return r}
